import ReactDOM from 'react-dom/client';

const path = window.location.pathname;
const isExecPage = path.includes('exec');
const isDarkStorePage = path.includes('dark_store');
const isFraudPage = path.includes('fraud');
const isHomePage = path.includes('home');

const App = isExecPage
 ? lazy(() => import('./exec-app'))
 : isDarkStorePage
 ? lazy(() => import('./dark-store-app'))
 : isFraudPage
 ? lazy(() => import('./fraud-app'))
 : isHomePage
 ? lazy(() => import('./home-app'))
 : lazy(() => import('./app'));

ReactDOM.createRoot(document.getElementById('root')!).render(
 <Suspense fallback={null}>
 <App />
 </Suspense>
);
